package com.aespejo.registrations.infrastructure.files;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Optional;
import java.util.UUID;
import java.util.stream.Collectors;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

/**
 * Stores uploaded files under a root folder outside the public web root. Names are generated by the server; the
 * relative path returned to callers is always resolved again inside the root before reading or deleting, so a stored
 * {@code ../} cannot point at another file. Ported from {@code AlmacenArchivosLocal}.
 */
@Component
public class FileStore {

    private final Path root;

    public FileStore(@Value("${files.base-path:App_Data/uploads}") String basePath) {
        this.root = Path.of(basePath).toAbsolutePath().normalize();
    }

    /** Saves the bytes under {@code folder} with a generated name and returns the relative path. */
    public String save(String folder, String extension, byte[] content) {
        String safeFolder = folder.chars().filter(c -> Character.isLetterOrDigit(c) || c == '-' || c == '_')
                .mapToObj(c -> String.valueOf((char) c)).collect(Collectors.joining());
        String name = UUID.randomUUID().toString().replace("-", "") + extension;
        Path directory = root.resolve(safeFolder);
        try {
            Files.createDirectories(directory);
            Files.write(directory.resolve(name), content);
        } catch (IOException e) {
            throw new IllegalStateException("The file could not be stored.", e);
        }
        return safeFolder + "/" + name;
    }

    public Optional<byte[]> read(String relativePath) {
        return resolve(relativePath).filter(Files::exists).map(p -> {
            try {
                return Files.readAllBytes(p);
            } catch (IOException e) {
                throw new IllegalStateException("The file could not be read.", e);
            }
        });
    }

    public void delete(String relativePath) {
        resolve(relativePath).ifPresent(p -> {
            try {
                Files.deleteIfExists(p);
            } catch (IOException e) {
                throw new IllegalStateException("The file could not be deleted.", e);
            }
        });
    }

    /** The absolute path of a relative one, or empty when it would fall outside the root. */
    private Optional<Path> resolve(String relativePath) {
        if (relativePath == null || relativePath.isBlank()) {
            return Optional.empty();
        }
        Path candidate = root.resolve(relativePath).normalize();
        return candidate.startsWith(root) ? Optional.of(candidate) : Optional.empty();
    }
}
